use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl < 'ast > Visit < 'ast > for CategorizationVisitor { fn visit_item_use (& mut self , i : & 'ast syn :: ItemUse) { if format ! ("{}" , quote :: quote ! (# i)) . contains ("syn") { self . analysis . uses_syn = true ; } syn :: visit :: visit_item_use (self , i) ; } fn visit_item_const (& mut self , i : & 'ast syn :: ItemConst) { self . analysis . defines_const = true ; syn :: visit :: visit_item_const (self , i) ; } fn visit_item_enum (& mut self , i : & 'ast syn :: ItemEnum) { self . analysis . defines_enum = true ; syn :: visit :: visit_item_enum (self , i) ; } fn visit_item_struct (& mut self , i : & 'ast syn :: ItemStruct) { self . analysis . defines_struct = true ; syn :: visit :: visit_item_struct (self , i) ; } fn visit_macro (& mut self , mac : & 'ast syn :: Macro) { if let Some (segment) = mac . path . segments . last () { self . analysis . calls_other_macros . push (segment . ident . to_string ()) ; } syn :: visit :: visit_macro (self , mac) ; } }
}